// Search-intent classification, validated against 2026 advertising research:
// high-intent = people actively search when they need it (Google-led);
// low-intent = discovery/visual businesses people don't search by category (streaming/social-led).
const HIGH_INTENT = ["HVAC", "Garbage / Waste", "Landscaping", "Plumbing", "Roofing", "Contracting", "Auto Repair", "Dentist", "Locksmith", "Law / Injury Firm", "Med Spa / Wellness", "Restaurant / Food", "Real Estate"];
const CATEGORIES = ["Select business type", "HVAC", "Garbage / Waste", "Landscaping", "Plumbing", "Roofing", "Contracting", "Auto Repair", "Dentist", "Locksmith", "Law / Injury Firm", "Restaurant / Food", "Charcuterie / Specialty Food", "Boutique / Retail", "Med Spa / Wellness", "Real Estate", "Event / Entertainment", "Other"];
const PLACEHOLDER_CAT = "Select business type";
const WEBSITE_FEE = 1000;
const AD_PRODUCTION = 1500;

const money = (n) => "$" + n.toLocaleString("en-US");
function fmtDate(iso) {
  if (!iso) return "";
  const [y, m, d] = iso.split("-").map(Number);
  if (!y || !m || !d) return iso;
  const months = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  return months[m - 1] + " " + d + ", " + y;
}

function buildPlan({ category, budget }) {
  const highIntent = HIGH_INTENT.includes(category);
  const lines = [];
  let rationaleLead = "";
  const cat = (category && category !== PLACEHOLDER_CAT) ? category : "Your business";
  if (highIntent) {
    rationaleLead = cat + " is something people actively search for the moment they need it, so we put your full budget into Google Ads to capture that existing demand at the exact moment it happens.";
    lines.push({ channel: "Google Ads", monthly: budget, why: "Captures high-intent searches, people looking for you right now, at the moment they need you." });
  } else {
    rationaleLead = cat + " is best reached by putting you directly in front of the right audience. We lead with OTT/CTV targeted advertising to reach the exact households most likely to buy, then layer social to reinforce it.";
    const ott = Math.min(budget, 2000);
    lines.push({ channel: "OTT / CTV Targeted Ads", monthly: ott, why: "Directly targets your ideal audience on premium streaming, the best reach for reaching buyers where they watch." });
    const remaining = budget - ott;
    if (remaining >= 250) lines.push({ channel: "Social Media Ads", monthly: remaining, why: "Reinforces the streaming campaign with retargeting across Instagram, Facebook, and TikTok." });
  }
  return { lines, rationaleLead, highIntent };
}

const ALLOC_CHANNELS = [
  { key: "OTT / CTV Targeted Ads", short: "OTT / CTV" },
  { key: "Google Ads", short: "Google Ads" },
  { key: "Social Media Ads", short: "Social Media" },
];
function defaultWhy(key) {
  if (key === "Google Ads") return "Captures high-intent searches, people looking for you right now.";
  if (key === "OTT / CTV Targeted Ads") return "Directly targets your ideal audience across premium streaming: Hulu, ESPN, Paramount+ and 550+ partners.";
  return "Reinforces the campaign with retargeting across Instagram, Facebook, and TikTok.";
}

function buildOpener({ contactFirst, clientName, highIntent, problem, category }) {
  const greet = contactFirst ? contactFirst + ", " : "";
  const biz = clientName || "your business";
  // Lowercased business type for the "X is something people search for" phrasing.
  const TYPE_PROSE = {
    "Garbage / Waste": "garbage and waste service",
    "Auto Repair": "auto repair",
    "Med Spa / Wellness": "med spa services",
    "Law / Injury Firm": "legal help",
    "Restaurant / Food": "your food",
    "Real Estate": "real estate",
    "Charcuterie / Specialty Food": "specialty food",
    "Boutique / Retail": "your shop",
    "Event / Entertainment": "your events",
  };
  const typeWord = (category && category !== PLACEHOLDER_CAT && category !== "Other") ? (TYPE_PROSE[category] || category.toLowerCase()) : "what you offer";
  const prob = (problem || "").trim();
  // If a problem is provided, lead with it (quoted), then pivot to the solution.
  if (prob) {
    const probClean = prob.replace(/\.+$/, "").replace(/^["']|["']$/g, "");
    const quoted = "\u201C" + probClean + "\u201D";
    const you = contactFirst ? "you" : "You";
    if (!highIntent) {
      return greet + you + " told us the challenge is " + quoted + ". This plan is built to fix exactly that. Your product is visual, and targeted streaming is the one channel that puts it full-screen in front of the households most likely to buy, with no way to skip past it, so the people who'd choose you finally see you.";
    }
    return greet + you + " told us the challenge is " + quoted + ". This plan is built to fix exactly that. Because " + typeWord + " is something people actively search for when they need it, we lead with Google Ads to catch that demand at the exact moment it happens, then reinforce it across targeted streaming and social so you stay top of mind: the name they find first, and the name they remember.";
  }
  if (!highIntent) {
    const lead = contactFirst ? "streaming" : "Streaming";
    return greet + lead + " is the right instinct for " + biz + ". Your product is visual, and targeted streaming is the one channel that puts it full-screen in front of the households most likely to buy, with no way to skip past it. This proposal is built entirely around that strength: getting you in front of the buyers most likely to choose you.";
  }
  const lead = contactFirst ? "because" : "Because";
  return greet + lead + " " + typeWord + " is something people actively search for when they need it, this plan leads with Google Ads to catch that demand at the exact moment it happens, then reinforces it across targeted streaming and social so you stay top of mind. The goal is simple: be the name they find first, and the name they remember.";
}

// POLITICAL service options
const POLI_SERVICES = [
  { id: "signs", name: "Yard signs & signage", desc: "Name-recognition signage placed throughout the community: yards, key intersections, and high-traffic areas across the district." },
  { id: "canvass", name: "Canvassing campaign", desc: "Our team goes door to door across targeted precincts to encourage turnout and put your message directly in voters' hands, the ground game that wins races. We use our own voter-mapping app that shows the party lean of each household (Republican, Democrat, or Independent), so your team spends its time at the doors that matter most." },
  { id: "ads", name: "Targeted streaming & digital ads", desc: "Full-screen, non-skippable video delivered to targeted households, concentrated in the precincts that decide the race." },
  { id: "shows", name: "Show appearances on our network", desc: "We bring you onto our local shows so voters get to know the person behind the name, the same programs that host council members, mayors, and candidates across the region." },
];

function buildPoliOpener({ contactFirst, candidateName, runningFor, where, problem }) {
  const who = candidateName || "your campaign";
  const seat = runningFor ? " for " + runningFor : "";
  const place = where ? " in " + where : "";
  const prob = (problem || "").trim();
  if (prob) {
    const probClean = prob.replace(/\.+$/, "").replace(/^["']|["']$/g, "");
    const quoted = "\u201C" + probClean + "\u201D";
    const greet2 = contactFirst ? contactFirst + ", you" : "You";
    return greet2 + " told us the challenge is " + quoted + ". This plan is built to meet it head-on. Races are won on the ground: name recognition, real conversations with voters, and showing up where the community already pays attention. This is an initial plan for " + who + seat + place + ", combining the tools that do exactly that, so we can shape the right mix together and put your name in front of the voters who decide this race.";
  }
  const greet = contactFirst ? contactFirst + ", races" : "Races";
  return greet + " are won on the ground: name recognition, real conversations with voters, and showing up where the community already pays attention. This is an initial plan for " + who + seat + place + ", combining the tools that do exactly that. Consider it a starting point, a conversation opener, so we can shape the right mix together and put your name in front of the voters who decide this race.";
}

