const css = `
* { -webkit-font-smoothing: antialiased; }
select option { color:#fff; background:#17181A; }
.date-input::-webkit-calendar-picker-indicator { filter: invert(1); opacity: 0.7; cursor: pointer; }
.date-input::-webkit-calendar-picker-indicator:hover { opacity: 1; }
.date-input::-webkit-datetime-edit { color: #fff; }
.opener-print { display: none; }
@media (max-width:860px){ div[style*='grid-template-columns: minmax']{ grid-template-columns:1fr !important; } }
input:focus,select:focus,button:focus-visible,textarea:focus{ outline:2px solid ${RED_HI}; outline-offset:2px; }
@media print {
  @page { size: letter; margin: 0.55in; }
  html, body { background: #fff !important; }
  .app-ui, .doc-toolbar { display: none !important; }
  .doc-overlay { position: static !important; background: #fff !important; }
  .doc-scroll { overflow: visible !important; padding: 0 !important; gap: 0 !important; display: block !important; background: #fff !important; }
  .proposal-doc { box-shadow: none !important; max-width: 100% !important; border-radius: 0 !important; padding: 0 !important; background: #fff !important; }
  .proposal-doc.page { break-after: page; page-break-after: always; }
  .proposal-doc.page:last-child { break-after: auto; page-break-after: auto; }
  .opener-edit { display: none !important; }
  .opener-print { display: block !important; }
  h2 { break-after: avoid; }
  li, tr { break-inside: avoid; }
}
`;
